import fs from 'node:fs';import os from 'node:os';import path from 'node:path';
import {setup} from '../tests/node-host.mjs';import {FomkyrEngine} from '../web/engine.js';
const temp=fs.mkdtempSync(path.join(os.tmpdir(),'fomkyr-tail-inspect-'));setup(temp);
const f=JSON.parse(fs.readFileSync('fixtures/fk6.json'));const e=new FomkyrEngine({workers:4,spill:true,budgetBytes:128*1048576,scratchBytes:32*1048576,hashBits:16,resume:false,hilbert:false,exportText:false,progress:false});
try{let r=await e.compute(f,Number(process.argv[2]??9),0);let start=performance.now(),before=0,after=0,rows=[];for(let i=1;i<=r.basisSize;i++){const n=Number(e.e.gn_rule_stat(i,3));before+=n;const o=Number(e.e.gn_canonical_rule(i));if(!o)throw Error(`canonical ${i} failed`);const k=new DataView(e.memory.buffer,o,32).getUint32(8,true);after+=k;if(n!==k)rows.push({id:i,d:Number(e.e.gn_rule_stat(i,2)),before:n,after:k});}let result={degree:r.target,before,after,ms:performance.now()-start,changed:rows.length,rows};fs.writeFileSync(`results/0.6/exploratory/tails-d${r.target}.json`,JSON.stringify(result,null,2));console.log(JSON.stringify({...result,rows:undefined}));}finally{await e.close();fs.rmSync(temp,{recursive:true,force:true});}
